source:
(sh) => {
    sh.uniforms.uTime = U.uTime;
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nattribute float aSeed;\nuniform float uTime;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>\nfloat dk = mod(uTime * ${spd} * (0.8 + 0.4 * aSeed) + aSeed * 37.0, ${len} + 1.5); transformed.y -= max(0.0, dk - 1.5) * max(0.0, dk - 1.5) / ${len};`);
  }

